// Package binary describes the binary installer's agent section (agent.binary):
// the container-run, locally-built Agent. It mirrors the environment schemas:
// one data-only type, validated and example-generated by the shared schema
// engine. There is deliberately no version or image field here — the Agent is
// always built from the working tree; a released version belongs to the script
// or helm installers.
package binary

import (
	"errors"
	"fmt"
	"regexp"

	"github.com/DataDog/datadog-agent/test/e2e-framework/cmd/internal/configschema"
	"go.yaml.in/yaml/v3"
)

// Config is what the binary installer consumes.
type Config struct {
	RuntimeImage string            `yaml:"runtime-image,omitempty" description:"Runtime image the built Agent runs in (default: the pinned official Agent image)."`
	Config       string            `yaml:"config,omitempty" description:"Extra datadog.yaml configuration."`
	Integrations map[string]string `yaml:"integrations,omitempty" description:"conf.d folder name -> its conf.yaml contents."`
}

var integrationPattern = regexp.MustCompile(`^[a-zA-Z0-9_.-]+\.d$`)

// Rules checks what annotations cannot: integration folder names and the
// embedded agent config being valid YAML — the same rules as the script
// section, so both host-side installers behave identically.
type Rules struct{}

func (Rules) Validate(c Config) error {
	for folder := range c.Integrations {
		if !integrationPattern.MatchString(folder) {
			return fmt.Errorf("integrations: %q is not a valid conf.d folder name", folder)
		}
	}
	if c.Config != "" {
		var out map[string]any
		if err := yaml.Unmarshal([]byte(c.Config), &out); err != nil {
			return errors.New("config: not valid YAML")
		}
	}
	return nil
}

// Schema is shared by the CLI adapters that validate, install and generate
// examples for the binary installer.
var Schema = configschema.Must[Config](Rules{})
